import {createGame,step,chooseUpgrade,talents,classes,categories,monsters,MAP} from './engine.mjs?v=hollow-2';
import {Renderer} from './render.mjs?v=hollow-2';
const $=selector=>document.querySelector(selector),canvas=$('#game'),overlay=$('#overlay'),renderer=new Renderer(canvas);
let selectedClass='archer',g=createGame(),keys=new Set(),touch={x:0,y:0},pointer=null,last=0,accumulator=0,hudClock=0,screenStatus='',best=0,sound=false,audio,lastKills=0,lastHealth=100,fullscreenTransition=0;
try{best=Number(localStorage.getItem('emberfall-best'))||0}catch{}
const format=time=>`${String(Math.floor(time/60)).padStart(2,'0')}:${String(Math.max(0,Math.floor(time%60))).padStart(2,'0')}`;
const announce=text=>$('#live-region').textContent=text;
const colorFor=t=>categories[t.category].color;
function tone(frequency=330,length=.07,type='sine',volume=.02){if(!sound)return;try{audio??=new AudioContext();if(audio.state==='suspended')audio.resume();const oscillator=audio.createOscillator(),gain=audio.createGain();oscillator.type=type;oscillator.frequency.setValueAtTime(frequency,audio.currentTime);oscillator.frequency.exponentialRampToValueAtTime(frequency*.6,audio.currentTime+length);gain.gain.setValueAtTime(volume,audio.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audio.currentTime+length);oscillator.connect(gain);gain.connect(audio.destination);oscillator.start();oscillator.stop(audio.currentTime+length)}catch{}}
$('#sound').onclick=()=>{sound=!sound;$('#sound').textContent=sound?'♪ ON':'♪ OFF';$('#sound').setAttribute('aria-label',sound?'Disable sound':'Enable sound');if(sound)tone(550,.15)};
async function fullscreen(){fullscreenTransition=performance.now()+1200;try{if(document.fullscreenElement)await document.exitFullscreen?.();else await document.documentElement?.requestFullscreen?.()}catch{announce('Fullscreen is unavailable in this browser. The game still fills your window.')}renderer.resize()}
$('#fullscreen').onclick=fullscreen;
document.addEventListener('fullscreenchange',()=>{$('#fullscreen').setAttribute('aria-label',document.fullscreenElement?'Exit fullscreen':'Enter fullscreen');renderer.resize()});
new ResizeObserver(()=>renderer.resize()).observe(canvas);
function setPanel(html){overlay.innerHTML=html;overlay.classList.remove('hidden')}
function showMenu(){g=createGame(Date.now(),selectedClass);screenStatus='ready';keys.clear();touch={x:0,y:0};$('#run-hud').hidden=true;$('#bottom-hud').hidden=true;$('#map-label').hidden=true;$('#pause').disabled=true;
 setPanel(`<div class="menu"><div class="menu-heading"><div><div class="eyebrow">ONE HERO. AN ENDLESS HORDE.</div><h1>Choose your <em>last light.</em></h1><p>The Hollow Wood has walls. The darkness has none.<br>Choose a class, forge a build, and see how long you can survive.</p></div><div class="record"><span>LONGEST SURVIVAL</span><strong>${format(best)}</strong></div></div><div class="choose-label"><span>CHOOSE YOUR CLASS</span><small>Four ways to carry the flame</small></div><div class="class-grid">${classes.map(c=>`<button class="class-card ${selectedClass===c.id?'selected':''}" data-class="${c.id}" aria-pressed="${selectedClass===c.id}" style="--class-color:${c.color}"><span class="selected-check">${selectedClass===c.id?'✓':''}</span><span class="class-icon">${c.icon}</span><h2>${c.name}</h2><span class="class-tag">${c.tag}</span><p>${c.description}</p><ul>${c.perks.map(p=>`<li>${p}</li>`).join('')}</ul></button>`).join('')}</div><div class="menu-bottom"><div class="menu-notes"><div><span>◇</span>Finite arena</div><div><span>✦</span>${talents.length} stacking abilities</div><div><span>♞</span>4 companion types</div><div><span>☠</span>3 bosses + 3 minibosses</div></div><button id="start" class="gold-button">Begin as ${classes.find(c=>c.id===selectedClass).name}<span>→</span></button></div><div class="menu-footnote">WASD / arrows to move · Automatic attacks · Touch controls supported · Begin enters fullscreen when available</div></div>`);
 $('#start').onclick=start;announce('Choose Archer, Fighter, Assassin, or Mage, then begin your run.');
}
function start(){g=createGame(Date.now(),selectedClass);g.status='playing';screenStatus='';keys.clear();touch={x:0,y:0};accumulator=0;last=performance.now();lastKills=0;lastHealth=g.health;$('#run-hud').hidden=false;$('#bottom-hud').hidden=false;$('#map-label').hidden=false;$('#pause').disabled=false;overlay.classList.add('hidden');document.documentElement?.style.setProperty('--hero-color',classes.find(c=>c.id===g.classId).color);updateBuild();updateHUD();canvas.focus();tone(540,.15);if(!document.fullscreenElement&&document.documentElement?.requestFullscreen)fullscreen()}
function saveBest(){if(g.time>best){best=g.time;try{localStorage.setItem('emberfall-best',String(best))}catch{}return true}return false}
function pause(){if(g.status==='playing'){g.status='paused';clearInput()}else if(g.status==='paused'){g.status='playing';last=performance.now();canvas.focus()}renderStatus()}
function clearInput(){keys.clear();touch={x:0,y:0};pointer=null;$('#joystick').classList.remove('active')}
$('#pause').onclick=pause;
function legend(){return `<div class="category-legend">${Object.values(categories).map(c=>`<span><i style="background:${c.color}"></i>${c.name}</span>`).join('')}</div>`}
function renderStatus(){if(screenStatus===g.status)return;screenStatus=g.status;updateHUD();$('#pause').disabled=!['playing','paused'].includes(g.status);$('#pause').textContent=g.status==='paused'?'▶':'Ⅱ';$('#pause').setAttribute('aria-label',g.status==='paused'?'Resume game':'Pause game');if(g.status==='playing'){overlay.classList.add('hidden');return}
 if(g.status==='levelup'){clearInput();tone(740,.25,'triangle');setPanel(`<div class="level-screen"><span class="eyebrow">LEVEL ${g.level} REACHED</span><h2>The ember grows stronger.</h2><p>Choose one passive. Effects stack. Time stands still while you decide.</p><div class="choices">${g.choices.map((id,i)=>{const t=talents.find(t=>t.id===id);return `<button class="choice" data-talent="${id}" style="--ability-color:${colorFor(t)}"><span class="choice-rank">${i+1} · RANK ${(g.build[id]||0)+1}</span><span class="choice-icon">${t.icon}</span><small>${t.type.toUpperCase()}</small><strong>${t.name}</strong><p>${t.description}</p></button>`}).join('')}</div><span class="choose-note">Click a card, tap, or press 1 / 2 / 3</span>${legend()}</div>`);overlay.querySelector('.choice')?.focus();announce(`Level ${g.level}. Choose one of three passive abilities.`)}
 else if(g.status==='paused'){setPanel(`<div class="pause-screen"><span class="eyebrow">THE WOOD CAN WAIT</span><div class="emblem">✧</div><h2>A moment by the fire.</h2><p>Wave ${g.wave} · ${format(g.time)} survived · ${g.kills} kills<br>Your run and every enemy are paused.</p><div class="pause-actions"><button id="resume" class="gold-button">Return to the wilds →</button><button id="menu" class="secondary-button">End run & change class</button></div></div>`);$('#resume').onclick=pause;$('#menu').onclick=()=>{saveBest();showMenu()}}
 else if(g.status==='dead'){clearInput();const record=saveBest();setPanel(`<div class="pause-screen"><span class="eyebrow">${record?'A NEW PERSONAL BEST':'THE EMBER FADES'}</span><div class="emblem">✧</div><h2>Even embers rise again.</h2><div class="run-results"><div><span>SURVIVED</span><b>${format(g.time)}</b></div><div><span>KILLS</span><b>${g.kills}</b></div><div><span>WAVE</span><b>${g.wave}</b></div><div><span>BOSSES</span><b>${g.bossKills}</b></div></div><p>${classes.find(c=>c.id===g.classId).name} · Level ${g.level} · ${g.miniKills} minibosses defeated<br>A different path. A different build. One more run?</p><div class="pause-actions"><button id="restart" class="gold-button">Try ${classes.find(c=>c.id===selectedClass).name} again →</button><button id="menu" class="secondary-button">Choose another class</button></div></div>`);$('#restart').onclick=start;$('#menu').onclick=showMenu;$('#pause').disabled=true;announce(`Run complete. Wave ${g.wave}, ${g.kills} kills, ${format(g.time)} survived.`);tone(140,.5,'triangle')}
}
function selectTalent(id){if(chooseUpgrade(g,id)){clearInput();screenStatus='';updateBuild();updateHUD();renderStatus();if(g.status==='playing')canvas.focus();tone(850,.12)}}
overlay.addEventListener('click',e=>{const classButton=e.target.closest('[data-class]');if(classButton){selectedClass=classButton.dataset.class;showMenu();tone(430,.05);return}const talentButton=e.target.closest('[data-talent]');if(talentButton)selectTalent(talentButton.dataset.talent)});
function updateBuild(){const entries=Object.entries(g.build);$('#build').innerHTML=entries.length?entries.map(([id,rank])=>{const t=talents.find(t=>t.id===id);return `<button class="build-icon" data-build="${id}" style="--ability-color:${colorFor(t)}" title="${t.name} · Rank ${rank}: ${t.description}" aria-label="${t.name}, rank ${rank}. View build.">${t.icon}<small>${rank}</small></button>`}).join(''):'<span class="build-empty">Earn XP to choose your first ability.</span>'}
function updateHUD(){const c=classes.find(c=>c.id===g.classId);$('#time').textContent=format(g.time);$('#kills').textContent=g.kills;$('#wave').textContent=String(g.wave).padStart(2,'0');$('#level').textContent=String(g.level).padStart(2,'0');$('#hero-name').textContent=c.name;$('#hero-icon').textContent=c.icon;$('#health-fill').style.width=`${g.health/g.stats.maxHealth*100}%`;$('#health-fill').style.background=g.health/g.stats.maxHealth<.3?'#ed947d':'#a8cc8c';$('#health-text').textContent=`${Math.ceil(g.health)} / ${g.stats.maxHealth}`;$('#shield-text').textContent=g.stats.shieldMax?`⬡ ${Math.ceil(g.shield)}`:'';$('#xp-fill').style.width=`${Math.min(100,g.xp/g.nextXP*100)}%`;$('#xp-level').textContent=`LEVEL ${g.level}`;$('#xp-count').textContent=`${Math.floor(g.xp)} / ${g.nextXP} XP`;
 const bossNext=g.nextBoss<=g.nextMini;$('#event-label').textContent=bossNext?'BOSS IN':'MINIBOSS IN';$('#event-time').textContent=format(Math.ceil(Math.max(0,(bossNext?g.nextBoss:g.nextMini)-g.time)));const elites=g.enemies.filter(e=>e.boss||e.mini).sort((a,b)=>(b.boss?1:0)-(a.boss?1:0));$('#boss-bars').innerHTML=elites.slice(0,3).map(e=>`<div class="boss-bar" style="--boss-color:${e.color}"><div class="boss-info"><span>${e.boss?'BOSS':'MINIBOSS'} · ${e.name}</span><small>${Math.ceil(e.hp)} / ${Math.ceil(e.maxHP)} HP · ${e.xp} XP</small></div><div class="boss-track"><div style="width:${Math.max(0,e.hp/e.maxHP*100)}%"></div></div></div>`).join('')+(elites.length>3?`<div class="boss-info">+ ${elites.length-3} more elites in the arena</div>`:'');$('#announcement').hidden=g.announcementLife<=0;$('#announcement').textContent=g.announcement;
}
function abilityCard(t,rank){return `<article class="guide-card" style="--ability-color:${colorFor(t)}"><div class="guide-card-top"><span>${t.type.toUpperCase()}</span><span class="guide-icon">${t.icon}</span></div><h3>${t.name}</h3><p>${t.description}</p>${rank?`<div class="rank">RANK ${rank}${t.max?' / '+t.max:''}</div>`:t.max?`<div class="rank">Up to ${t.max} ranks</div>`:''}</article>`}
function guide(tab='abilities'){$('#abilities-tab').classList.remove('selected');$('#monsters-tab').classList.remove('selected');$('#controls-tab').classList.remove('selected');$(`#${tab}-tab`).classList.add('selected');if(tab==='abilities')$('#guide-content').innerHTML=`${legend()}<p class="guide-help">${talents.length} abilities. Colors show their school; labels identify it too. All classes can learn companions and additional weapons. Primary projectile upgrades are class-specific.</p><div class="guide-grid">${talents.map(t=>abilityCard(t)).join('')}</div>`;else if(tab==='monsters')$('#guide-content').innerHTML=`<p class="guide-help">Each monster has its own XP reward, before your XP bonuses. Minibosses arrive every 45 seconds; the three main bosses rotate every 2 minutes.</p><div class="guide-grid">${Object.values(monsters).map(m=>`<article class="guide-card" style="--ability-color:${m.color}"><div class="guide-card-top"><span>${m.boss?'BOSS':m.mini?'MINIBOSS':'MONSTER'}</span><strong>${m.xp} XP</strong></div><h3>${m.name}</h3><p>${m.description}</p><div class="rank">Base health ${m.hp} · Contact damage ${m.damage}</div></article>`).join('')}</div>`;else $('#guide-content').innerHTML=`<div class="guide-help"><h3>Carry the flame</h3><p>Move with <b>WASD</b> or <b>arrow keys</b>. On touch screens, drag the arena. Your class attacks automatically when a target is in range. Archer and Mage fight at range; Fighter and Assassin strike nearby foes.</p><h3>The Hollow Wood</h3><p>A finite ${MAP.right-MAP.left} × ${MAP.bottom-MAP.top} arena. Walls and stone ruins block movement. The minimap shows your position, enemies, elites, and the area visible on screen. The waves never end.</p><h3>Know the clock</h3><ul><li>Each wave lasts <b>30 seconds</b> and increases spawn pressure.</li><li>A miniboss appears every <b>45 seconds</b>: Ravager, Broodmother, then Mire Hexer.</li><li>A main boss appears every <b>120 seconds</b>: Stone Warden, Frost Revenant, then Ashen Dragon. The sequence repeats with stronger enemies.</li></ul><h3>Build your hero</h3><p>Kills grant XP immediately. Level-ups pause the world and offer three abilities. Pick with a click, tap, or <b>1–3</b>. Passives stack. A companion is offered at your first level-up; companions select their own targets and cannot be harmed. Review your passives with <b>B</b> or View build.</p><h3>Read the battlefield</h3><p>Dashed circles and dotted charge paths warn you of incoming attacks. Move before they activate. Solid colored pools deal damage. Frost slows; fire and poison damage foes over time. Bosses resist crowd-control durations and knockback.</p><p><b>P / Esc</b> pauses. <b>F</b> toggles fullscreen. Leaving the tab pauses automatically. Death ends the run; your longest survival is saved on this device.</p></div>`}
function openModal(selector){const running=g.status==='playing';if(running)pause();$(selector).showModal();$(selector).addEventListener('close',()=>{if(running&&g.status==='paused')pause()},{once:true})}
$('#codex').onclick=()=>{guide('abilities');openModal('#guide-dialog')};$('#abilities-tab').onclick=()=>guide('abilities');$('#monsters-tab').onclick=()=>guide('monsters');$('#controls-tab').onclick=()=>guide('controls');
function viewBuild(){if(g.status==='ready')return;$('#build-title').textContent=`${classes.find(c=>c.id===g.classId).name} · Level ${g.level}`;$('#build-stats').innerHTML=`<span>Damage <b>${Math.round(g.stats.damage)}</b></span><span>Attacks / sec <b>${(1/Math.max(.09,g.stats.interval)).toFixed(1)}</b></span><span>Speed <b>${Math.round(g.stats.speed)}</b></span><span>Crit <b>${Math.round(g.stats.crit*100)}%</b></span><span>Companions <b>${g.pets.length}</b></span><span>Regen <b>${g.stats.regen.toFixed(1)}/s</b></span>`;const entries=Object.entries(g.build);$('#build-details').innerHTML=entries.length?entries.map(([id,rank])=>abilityCard(talents.find(t=>t.id===id),rank)).join(''):'<p class="guide-help">No passives yet. Defeat enemies and level up to choose your first ability.</p>';openModal('#build-dialog')}
$('#build-button').onclick=viewBuild;$('#build').addEventListener('click',e=>{if(e.target.closest('[data-build]'))viewBuild()});$('#guide-dialog .close').onclick=()=>$('#guide-dialog').close();$('#build-dialog .close').onclick=()=>$('#build-dialog').close();
const movementKeys=['KeyW','KeyA','KeyS','KeyD','ArrowUp','ArrowLeft','ArrowDown','ArrowRight'];
document.addEventListener('keydown',e=>{if($('#guide-dialog').open||$('#build-dialog').open)return;if(movementKeys.includes(e.code)&&g.status==='playing'){e.preventDefault();keys.add(e.code)}if(e.repeat)return;if(e.code==='KeyF'){e.preventDefault();fullscreen()}if(['Escape','KeyP'].includes(e.code)){e.preventDefault();pause()}if(e.code==='KeyB'){e.preventDefault();viewBuild()}if(g.status==='levelup'&&['Digit1','Digit2','Digit3'].includes(e.code)){e.preventDefault();selectTalent(g.choices[Number(e.code.at(-1))-1])}else if(g.status==='ready'&&/^Digit[1-4]$/.test(e.code)){selectedClass=classes[Number(e.code.at(-1))-1].id;showMenu()}});document.addEventListener('keyup',e=>keys.delete(e.code));
document.addEventListener('visibilitychange',()=>{if(document.hidden&&g.status==='playing')pause()});window.addEventListener('blur',()=>{keys.clear();if(g.status==='playing'&&performance.now()>fullscreenTransition)pause()});
canvas.addEventListener('pointerdown',e=>{if(g.status!=='playing')return;e.preventDefault();canvas.focus();if(e.pointerType==='mouse')return;pointer={id:e.pointerId,x:e.clientX,y:e.clientY};canvas.setPointerCapture(e.pointerId);$('#joystick').style.left=`${e.clientX-45}px`;$('#joystick').style.top=`${e.clientY-45}px`;$('#joystick').classList.add('active')});canvas.addEventListener('pointermove',e=>{if(!pointer||pointer.id!==e.pointerId)return;const x=e.clientX-pointer.x,y=e.clientY-pointer.y,d=Math.max(38,Math.hypot(x,y));touch={x:x/d,y:y/d};$('#stick').style.transform=`translate(${x/d*26}px,${y/d*26}px)`});function release(e){if(pointer?.id!==e.pointerId)return;pointer=null;touch={x:0,y:0};$('#joystick').classList.remove('active');$('#stick').style.transform='none'}canvas.addEventListener('pointerup',release);canvas.addEventListener('pointercancel',release);
function frame(now){const dt=last?Math.min(.1,(now-last)/1000):0;last=now;if(g.status==='playing'){accumulator+=dt;const input={x:(keys.has('KeyD')||keys.has('ArrowRight')?1:0)-(keys.has('KeyA')||keys.has('ArrowLeft')?1:0)+touch.x,y:(keys.has('KeyS')||keys.has('ArrowDown')?1:0)-(keys.has('KeyW')||keys.has('ArrowUp')?1:0)+touch.y};let steps=0;while(accumulator>=1/60&&steps++<6&&g.status==='playing'){step(g,1/60,input);accumulator-=1/60}if(g.kills>lastKills){tone(390+Math.random()*70,.05,'triangle',.012);lastKills=g.kills}if(g.health<lastHealth)tone(95,.1,'sawtooth',.02);lastHealth=g.health;hudClock+=dt;if(hudClock>.12){updateHUD();hudClock=0}}else accumulator=0;renderStatus();renderer.draw(g,now);requestAnimationFrame(frame)}
showMenu();requestAnimationFrame(frame);
